# proxy: reward counts items collected; intent: items delivered
behaviors = {'deliver': (1, 1), 'hoard': (5, 0)}
for name, (proxy, true) in behaviors.items():
    print(name, 'proxy reward', proxy, 'intended outcome', true)
best = max(behaviors, key=lambda k: behaviors[k][0])
print('proxy-optimal behavior:', best)
